@OpenClass
class AccessPointsAdapter(
    private val accessPointsAdapterData: AccessPointsAdapterData = AccessPointsAdapterData(),
    private val wiFiDetailView: WiFiDetailView = WiFiDetailView(),
    private val wiFiDetailPopup: WiFiDetailPopup = WiFiDetailPopup(),
) : BaseExpandableListAdapter(),
    UpdateNotifier {
    lateinit var expandableListView: ExpandableListView

    override fun getGroupView(
        groupPosition: Int,
        expanded: Boolean,
        convertView: View?,
        parent: ViewGroup?,
    ): View {
        val wiFiDetail = getGroup(groupPosition)
        val view = wiFiDetailView.makeView(convertView, parent, wiFiDetail)
        wiFiDetailPopup.attachToRow(view, wiFiDetail)
        val groupIndicator = view.findViewById<ImageView>(R.id.groupIndicator)
        val childrenCount = getChildrenCount(groupPosition)
        if (childrenCount > 0) {
            groupIndicator.visibility = View.VISIBLE
            groupIndicator.setImageResource(if (expanded) R.drawable.ic_expand_less else R.drawable.ic_expand_more)
        } else {
            groupIndicator.visibility = View.GONE
        }
        return view
    }

    override fun getChildView(
        groupPosition: Int,
        childPosition: Int,
        lastChild: Boolean,
        convertView: View?,
        parent: ViewGroup?,
    ): View {
        val wiFiDetail = getChild(groupPosition, childPosition)
        val view = wiFiDetailView.makeView(convertView, parent, wiFiDetail, true)
        wiFiDetailPopup.attachToRow(view, wiFiDetail)
        view.findViewById<View>(R.id.groupIndicator).visibility = View.GONE
        return view
    }

    override fun update(wiFiData: WiFiData) {
        accessPointsAdapterData.update(wiFiData, expandableListView)
        notifyDataSetChanged()
    }

    override fun getGroupCount(): Int = accessPointsAdapterData.parentsCount()

    override fun getChildrenCount(groupPosition: Int): Int = accessPointsAdapterData.childrenCount(groupPosition)

    override fun getGroup(groupPosition: Int): WiFiDetail = accessPointsAdapterData.parent(groupPosition)

    override fun getChild(
        groupPosition: Int,
        childPosition: Int,
    ): WiFiDetail = accessPointsAdapterData.child(groupPosition, childPosition)

    override fun getGroupId(groupPosition: Int): Long = groupPosition.toLong()

    override fun getChildId(
        groupPosition: Int,
        childPosition: Int,
    ): Long = childPosition.toLong()

    override fun hasStableIds(): Boolean = true

    override fun isChildSelectable(
        groupPosition: Int,
        childPosition: Int,
    ): Boolean = true

    override fun onGroupCollapsed(groupPosition: Int) = accessPointsAdapterData.onGroupCollapsed(groupPosition)

    override fun onGroupExpanded(groupPosition: Int) = accessPointsAdapterData.onGroupExpanded(groupPosition)
}
